import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"DIVISIONE FRA POLINOMI","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/ad/ad5b.md","filePath":"lezioni/a_algebra/ad/ad5b.md"}`),a={name:`lezioni/a_algebra/ad/ad5b.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="divisione-fra-polinomi" tabindex="-1">DIVISIONE FRA POLINOMI <a class="header-anchor" href="#divisione-fra-polinomi" aria-label="Permalink to “DIVISIONE FRA POLINOMI”">​</a></h1><h2 id="metodo-di-ruffini" tabindex="-1">METODO DI RUFFINI <a class="header-anchor" href="#metodo-di-ruffini" aria-label="Permalink to “METODO DI RUFFINI”">​</a></h2><p>In Matematica occorre sempre cercare di fare prima e meglio, cioè la matematica è la scienza del massimo rendimento con il minimo sforzo.</p><p>Ruffini, osservando la divisione fra un polinomio ed un binomio si accorse che parecchie cose erano superflue, quindi elaborò una divisione più semplice. Purtroppo si può applicare solo quando dividiamo un polinomio per un binomio di primo grado, però vedrai che dovrai usarla moltissimo.</p><p>Osservando la divisione fra polinomi già vista nella pagina precedente puoi notare che si incolonnano tutti i termini simili (con le stesse lettere alla stessa potenza), quindi non c&#39;è bisogno di scrivere le lettere; basterà scrivere i numeri e le lettere saranno sottointese. Inoltre, poiché divido per un binomio, il risultato avrà un termine meno del polinomio di partenza, quindi l&#39;ultimo termine del polinomio lo scrivo fuori delle sbarre.</p><blockquote><p>Consideriamo poi che quello che conta nella divisione è il secondo termine del divisore [perché il primo rimoltiplicato viene uguale e di segno contrario, quindi va via]{.text-blue} e siccome quando moltiplico dovrei cambiare di segno, invece di cambiare di segno il risultato cambio lui di segno e lo scrivo a sinistra.</p></blockquote><p>Adesso inizio la divisione: abbasso il primo termine.</p><p>Poi lo moltiplico per il numero a sinistra e scrivo il risultato sotto il secondo termine (ma sopra la sbarra orizzontale).</p><p>Ora faccio la somma algebrica dei termini nella seconda colonna e scrivo il risultato sotto la sbarra.</p><p>Ora ripeto: moltiplico il divisore per il numero ottenuto e scrivo il risultato nella terza colonna sopra la sbarra.</p><p>Infine sommo in colonna e la divisione è terminata. Il termine <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> fuori delle sbarre sarà il resto, mentre per ottenere il risultato devo rimettere le lettere ai termini: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> sarà il termine noto, mentre a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> dovrò mettere <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>. Quindi il risultato è: <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>x</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">2x+1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> con resto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">= 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>.</p><p>Se osservi le due figure successive e guardi i riquadri blu ti puoi rendere conto che la divisione è la stessa fatta prima.</p><p><a href="./esruf/3ga.html">Ho bisogno di altre spiegazioni</a></p><p>Ora su questo argomento è bene fare molti <a href="./ad5b1.html" class="text-red">esercizi</a>.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};